 51 | /** Bounded operator observations. Runtime receipts remain the execution authority. */
 52 | export class MonitorStore {
 53 |   readonly instanceId = randomUUID();
 54 |   readonly startedAt = new Date().toISOString();
 55 |   readonly maxTasks: number;
 56 |   readonly maxEvents: number;
 57 |   readonly maxSourceBytes: number;
 58 |   private tasks = new Map<string, TaskDetail>();
 59 |   private directory?: string;
 60 |   private secrets: string[];
 61 |   private timer?: ReturnType<typeof setTimeout>;
 62 |   private writes: Promise<void> = Promise.resolve();
 63 |   private cursor = 0;
 64 |   private persistence: 'MEMORY' | 'HEALTHY' | 'DEGRADED';
 65 |   private persistenceError: string | null = null;
 66 | 
 67 |   constructor(options: Options = {}) {
 68 |     this.maxTasks = options.maxTasks ?? 256;
 69 |     this.maxEvents = options.maxEvents ?? 512;
 70 |     this.maxSourceBytes = options.maxSourceBytes ?? 8 * 1024 * 1024;
 71 |     for (const value of [this.maxTasks, this.maxEvents, this.maxSourceBytes])
 72 |       if (!Number.isSafeInteger(value) || value < 1) throw new Error('Invalid monitor retention limit');
 73 |     this.directory = options.directory;
 74 |     this.secrets = (options.secrets ?? []).filter(Boolean);
 75 |     this.persistence = this.directory ? 'HEALTHY' : 'MEMORY';
 76 |     if (this.directory) this.restore();
 77 |   }
 78 |   private text(value: unknown, max = 512): string {
 79 |     let text = typeof value === 'string' ? value : '';
 80 |     for (const secret of this.secrets) text = text.split(secret).join('[REDACTED]');
 81 |     return text.replace(/Bearer\s+[^\s"']+/gi, 'Bearer [REDACTED]').slice(0, max);
 82 |   }
 83 |   private restore() {
 84 |     const file = join(this.directory!, 'observations.json');
 85 |     if (!existsSync(file)) return;
 86 |     try {
 87 |       const bytes = readFileSync(file);
 88 |       if (bytes.length > 64 * 1024 * 1024) throw new Error('Monitor history exceeds recovery limit');
 89 |       const saved = JSON.parse(bytes.toString('utf8'));
 90 |       if (saved.schemaVersion !== VERSION || !Array.isArray(saved.tasks)) throw new Error('Unknown monitor history version');
 91 |       this.cursor = saved.cursor;
 92 |       for (const task of saved.tasks.slice(-this.maxTasks) as TaskDetail[]) {
 93 |         if (!task.id || !Array.isArray(task.events) || !Array.isArray(task.codes) || !Array.isArray(task.models))
 94 |           throw new Error('Invalid monitor history');
 95 |         if (task.status === 'RUNNING') {
 96 |           task.status = 'INTERRUPTED'; task.stage = 'NODE_RESTARTED';
 97 |           task.reconciliationRequired = true;
 98 |           for (const call of task.models) if (call.status === 'RUNNING') call.status = 'UNKNOWN';
